//! The UI's copy: messages, commands and events as one TypeScript module.

use crate::catalog;
use substrate_message::camel;

/// The templates as a TypeScript module: `messages.<group>.<name>`.
pub fn typescript() -> String {
    let mut out = String::from(
        "// Generated by substrate-platform (`cargo run -p substrate-host-contract --all-features --bin substrate-messages`) — don't edit.\n\n/** Substrate's message templates: the i18n catalogs' keys for what the backend says. */\nexport const messages = {\n",
    );
    let mut groups: Vec<&str> = catalog().iter().map(|(g, _, _)| *g).collect();
    groups.dedup();
    for group in groups {
        out.push_str(&["  ", group, ": {\n"].concat());
        for (_, name, text) in catalog().iter().filter(|(g, _, _)| *g == group) {
            out.push_str(&["    ", &camel(name), ": ", &format!("{text:?}"), ",\n"].concat());
        }
        out.push_str("  },\n");
    }
    out.push_str("} as const;\n\n");
    out.push_str(&crate::commands::typescript(
        "substrate",
        "Substrate's host commands by domain: `substrate.<domain>.<command>`, for `invokeCommand`.",
        crate::commands::SUBSTRATE,
    ));
    out.push('\n');
    out.push_str(&crate::events::typescript(
        "events",
        "The events Substrate's host sends its UI.",
        crate::events::ALL,
    ));
    out
}
